-- SAP HANA Cloud schema for the HANARepository adapter (REPOSITORY=hana).
CREATE SCHEMA "EQUALPATH";

CREATE COLUMN TABLE "EQUALPATH"."DOCUMENTS" (
  "COLLECTION" NVARCHAR(64) NOT NULL,
  "DOC_ID"     NVARCHAR(128) NOT NULL,
  "OWNER_ID"   NVARCHAR(64),
  "BODY"       NCLOB NOT NULL,
  "UPDATED_AT" NVARCHAR(40) NOT NULL,
  PRIMARY KEY ("COLLECTION", "DOC_ID")
);
CREATE INDEX "IX_DOCUMENTS_OWNER" ON "EQUALPATH"."DOCUMENTS" ("OWNER_ID");

CREATE COLUMN TABLE "EQUALPATH"."AUDIT_EVENTS" (
  "SEQ"          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "EVENT_ID"     NVARCHAR(32) NOT NULL UNIQUE,
  "TS"           NVARCHAR(40) NOT NULL,
  "EVENT_TYPE"   NVARCHAR(64) NOT NULL,
  "ACTOR"        NVARCHAR(200) NOT NULL,
  "RUN_ID"       NVARCHAR(64),
  "CANDIDATE_ID" NVARCHAR(64),
  "SUMMARY"      NVARCHAR(1000) NOT NULL,
  "DETAILS"      NCLOB NOT NULL,
  "PREV_HASH"    NVARCHAR(64) NOT NULL,
  "HASH"         NVARCHAR(64) NOT NULL
);

-- Immutability: the application user may only INSERT and SELECT audit events.
CREATE USER EQUALPATH_APP PASSWORD "<set-a-strong-password>" NO FORCE_FIRST_PASSWORD_CHANGE;
GRANT SELECT, INSERT, UPDATE, DELETE ON "EQUALPATH"."DOCUMENTS" TO EQUALPATH_APP;
GRANT SELECT, INSERT ON "EQUALPATH"."AUDIT_EVENTS" TO EQUALPATH_APP;
